		["Do you seek a passage to the"] = "Procura uma passagem para o",
		["Do you seek a ride to"] = "Você procura uma carona para",
		["Do you seek a shortcut passage to {Thais} for 100 gold, to {Edron} for 90 gold, to {Liberty Bay} for 20 gold or to {Yalahar} for 200 gold?"] = "Procura um atalho de passagem para {Thais} por 100 gold, para {Edron} por 90 gold, para {Liberty Bay} por 20 gold ou para {Yalahar} por 200 gold?",
		["Do you want a passage to"] = "Você quer uma passagem para",
		["Do you want go to"] = "Você quer ir para",
		["Do you want go to the"] = "Quer ir para",
		["Do you want me take you to {Cormaya}, {Farmine} or to {Gnomprona}?"] = "Quer que eu o leve para {Cormaya}, {Farmine} ou para {Gnomprona}?",
		["Do you want me take you to {Cormaya}, {Kazordoon} or {Gnomprona}?"] = "Quer que eu o leve para {Cormaya}, {Kazordoon} ou {Gnomprona}?",
		["Do you want me to inspect a diary?"] = "Quer que eu examine um diário?",
		["Do you want me to repeat the task requirements?"] = "Quer que eu repita os requisitos da tarefa?",
		["Do you want some mushroom beer for 10 gold?"] = "Quer um pouco de mushroom beer por 10 gold?",
		["Do you want to Nibelor?"] = "Quer ir para Nibelor?",
		["Do you want to appropriately show off your boss trophies and buy an additional podium of vigour for 1000000 Gold?"] = "Quer exibir seus troféus de boss como merecem e comprar mais um podium of vigour por 1000000 de ouro?",
		["Do you want to be promoted in your vocation for 20000 gold?"] = "Quer ser promovido na sua vocação por 20000 gold?",
		["Do you want to buy a 'mace of the fury' for 250 gold?"] = "Quer comprar uma 'mace of the fury' por 250 gold?",
