		["my support spells are: {arrow call}, {cancel invisibility}, {find fiend}, {find person}, {great light}, {haste}, {lesser ethereal spear}, {levitate}, {light} and {magic rope}"] = "Minhas magias de suporte são: {Arrow Call}, {Cancel Invisibility}, {Find Fiend}, {Find Person}, {Great Light}, {Haste}, {Lesser Ethereal Spear}, {Levitate}, {Light} e {Magic Rope}.",
		["my support spells are: {arrow call}, {conjure arrow} and {conjure explosive arrow}"] = "Minhas magias de suporte são: {Arrow Call}, {Conjure Arrow} e {Conjure Explosive Arrow}.",
		["my support spells are: {arrow call}, {conjure arrow}, {conjure explosive arrow}, {find fiend}, {find person}, {great light} and {light}"] = "Minhas magias de suporte são: {Arrow Call}, {Conjure Arrow}, {Conjure Explosive Arrow}, {Find Fiend}, {Find Person}, {Great Light} e {Light}.",
